{
  "claims": [
    {
      "text": "Raw persistence is essential for auditability and reconstruction of complex ceremonies, as demonstrated by the successful reconstruction of run csi-typha-appeal-1 from raw Loki logs.",
      "evidence_refs": ["ev-t4-loki-raw-value"]
    },
    {
      "text": "Summarization introduces significant risks of drift and fabrication, as shown in real runs where summaries incorrectly asserted 'privileged:true' without source confirmation.",
      "evidence_refs": ["ev-t4-summary-drift-risk"]
    },
    {
      "text": "Storage costs for full outputs are negligible compared to compute costs, making raw persistence financially feasible.",
      "evidence_refs": ["ev-t4-storage-cost"]
    },
    {
      "text": "Raw persistence increases audit surface due to potential PII in full outputs, necessitating retention policies for either form.",
      "evidence_refs": ["ev-t4-pii-surface"]
    },
    {
      "text": "Preview truncation in engine logs creates a risk of losing complete outputs if consumers discard the final RunCeremony response.",
      "evidence_refs": ["ev-t4-preview-truncation"]
    }
  ],
  "decision": "accept",
  "risks": [
    "Retaining raw outputs may increase exposure to PII if not properly governed.",
    "The system must ensure that raw outputs are handled securely to mitigate audit surface risks."
  ],
  "assumptions": [
    "The system has adequate mechanisms for PII handling and retention policy enforcement.",
    "Raw output persistence does not significantly impact performance or scalability under current load."
  ]
}
